@pytest.mark.parametrize("conflict", [False, True]) def test_fresh_process_writers_share_registry_lock(trio, tmp_path, conflict): roots, cards = trio helper = tmp_path / "writer.py" helper.write_text('''import json,sys,time from pathlib import Path from saimail import workspace from sailang import SailangError local,peer,card,alias,ready,go=sys.argv[1:] view=workspace.load_workspace_headers(local) payload=json.loads(Path(card).read_text()) Path(ready).write_text("ready") deadline=time.monotonic()+15 while not Path(go).exists(): if time.monotonic()>deadline: raise RuntimeError("test start gate timed out") time.sleep(.01) try: result=workspace.add_recipient(view,alias,payload,peer) except SailangError as e: result={"status":e.code} print(json.dumps(result)) ''', encoding="utf-8") env = os.environ.copy() env["PYTHONPATH"] = str(ROOT) + os.pathsep + env.get("PYTHONPATH", "") go = tmp_path / "go" ready = [tmp_path / f"ready-{i}" for i in range(2)] procs = [] foreign = [snapshot(root) for root in roots[1:]] try: for i in range(2): card = tmp_path / f"card-{i}.json" card.write_text(json.dumps(cards[i]), encoding="utf-8") alias = "same" if conflict else ("beta", "gamma")[i] procs.append(subprocess.Popen([sys.executable, str(helper), str(roots[0]), str(roots[i + 1]), str(card), alias, str(ready[i]), str(go)], cwd=ROOT, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)) deadline = time.monotonic() + 15 while not all(p.exists() for p in ready): assert time.monotonic() < deadline, "fresh process setup timed out" time.sleep(0.01) go.write_text("start", encoding="utf-8") results = [] for proc in procs: out, err = proc.communicate(timeout=20) assert proc.returncode == 0 and not err, (out, err) results.append(json.loads(out)) finally: for proc in procs: if proc.poll() is None: proc.kill() proc.communicate() peers = workspace.load_workspace_headers(roots[0]).peers if conflict: > assert sorted(r["status"] for r in results) == sorted([ workspace.RECIPIENT_ADDED, workspace.RECIPIENT_CONFLICT]) E AssertionError: assert ['RECIPIENT_A...IPIENT_ADDED'] == ['RECIPIENT_A...ENT_CONFLICT'] E E At index 1 diff: 'RECIPIENT_ADDED' != 'RECIPIENT_CONFLICT' E Use -v to get more diff
